  static RectTransform Rect(string name,Transform parent,float x,float y,float w,float h){var r=new GameObject(name,typeof(RectTransform)).GetComponent<RectTransform>();r.SetParent(parent,false);r.anchorMin=r.anchorMax=new Vector2(0,1);r.pivot=new Vector2(0,1);r.anchoredPosition=new Vector2(x,-y);r.sizeDelta=new Vector2(w,h);return r;}
  static RectTransform Full(string name,Transform parent){var r=Rect(name,parent,0,0,0,0);Stretch(r);return r;}static void Stretch(RectTransform r){r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.offsetMin=r.offsetMax=Vector2.zero;}static void Right(RectTransform r){r.anchorMin=r.anchorMax=new Vector2(1,r.anchorMin.y);}static void Bottom(RectTransform r){r.anchorMin=r.anchorMax=new Vector2(r.anchorMin.x,0);}static void Center(RectTransform r){r.anchorMin=r.anchorMax=new Vector2(.5f,.5f);}
