 static class LayoutExtensions {public static void AnchorRight(this RectTransform r){r.anchorMin=r.anchorMax=new Vector2(1,r.anchorMin.y);}public static void AnchorBottom(this RectTransform r){r.anchorMin=r.anchorMax=new Vector2(r.anchorMin.x,0);}public static void StretchAll(this RectTransform r){r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.offsetMin=r.offsetMax=Vector2.zero;}}
